    "answer": "(1) k+r ≤ 2^r-1",
    "blanks": [
      "k+r ≤ 2^r-1"
    ],
    "analysis": {
      "tag": "海明码;校验位位数",
      "detail": "海明码需满足:r 位校验位能表示 k+r 种状态,其中 1 种表示无错,其余 k+r 种用于指明每个数据位/校验位出错位置(共 k+r 位)。因此 2^r ≥ k+r+1,即 **2^r - 1 ≥ k + r**,等价于 k+r ≤ 2^r - 1。"
    }
