    "question": "某浮点数字长为16位，其中阶码6位，含1位阶符，移码表示;尾数10位，含1位数符，原码表示，规格化。那么   ①该浮点数可表示的非零最小正数的二进制代码是____，对应的十进制真值是____;   ②该浮点数可表示的最大正数的二进制代码是____，对应的十进制真值是____;   ③该浮点数可表示的绝对值最小负数的二进制代码是____，对应的十进制真值是____;   ④该浮点数可表示的绝对值最大负数的二进制代码是____，对应的十进制真值是____。",
    "answer": "(1) ①000000_2┆0.100000000_2; (2) 2^{-33}; (3) ②111111_2┆0.111111111_2; (4) 2^{31}·(1-2^{-9}); (5) ③000000_2┆1.100000000_2; (6) -2^{-33}; (7) ④111111_2┆1.111111111_2; (8) -2^{31}·(1-2^{-9})",
    "blanks": [
      "①000000_2┆0.100000000_2",
      "2^{-33}",
      "②111111_2┆0.111111111_2",
      "2^{31}·(1-2^{-9})",
      "③000000_2┆1.100000000_2",
      "-2^{-33}",
      "④111111_2┆1.111111111_2",
      "-2^{31}·(1-2^{-9})"
    ],
    "analysis": {
      "tag": "浮点数表示、规格化、IEEE/非标准",
      "detail": "阶码 6 位(含 1 位阶符)用移码表示,最小阶 = -2^5 = -32(代码 000000),最大阶 = 2^5-1 = 31(代码 111111)。尾数原码规格化,正尾数最小 0.1,最大 0.111111111。\r\n(1) 最小正数:阶码最小、尾数最小正 0.1 → 代码 000000_2 ┊ 0.100000000_2,真值 2^{-32} × 0.1 = 2^{-33}。\r\n(2) 最大正数:阶码最大、尾数最大正 0.111111111 → 代码 111111_2 ┊ 0.111111111_2,真值 2^{31} × (1 - 2^{-9})。\r\n(3) 绝对值最小负数:阶码最小、尾数最小 1.100000000(原码),真值 -2^{-33}。\r\n(4) 绝对值最大负数:阶码最大、尾数最大 1.111111111(原码),真值 -2^{31} × (1 - 2^{-9})。"
    }
