      "detail": "DMA 响应过程与中断有本质不同。DMA 传送过程中,CPU 并不切换到 DMA 服务程序,CPU 只是让出总线(或在周期挪用方式下被短暂打断当前存取周期),继续执行原程序指令流;因此 CPU 不需要保存断点和现场,也不存在\"返回\"的问题。题干把 DMA 当成\"中断\"来理解是错误的。"
