      "detail": "**(1) 算盘/算筹 vs 现代计算机**\r\n- 算盘/算筹:依赖**人**拨动珠子/摆放算筹,**不能自动执行**程序\r\n- 现代计算机:输入**程序后自动执行**,人只需要写程序和提供数据\r\n- **核心差距:自动化**\r\n\r\n**(2) 现代计算机应具备的四大功能**\r\n\r\n| 功能 | 含义 | 对应硬件 |\r\n|---|---|---|\r\n| **① 内动力** | 适合工作的原动力 | 电源、时钟 |\r\n| **② 内程序** | 内置程序执行机制 | CPU(指令系统 + 控制器) |\r\n| **③ 存储** | 程序和数据的存储与表示 | 存储器(主存 + 辅存) |\r\n| **④ 自我管理** | 系统运行中的自我管理 | 中断、异常、操作系统 |\r\n\r\n**对比计算机的\"自动\"工作流**:\r\n- 通电 → 启动程序(BIOS/引导) → CPU 读指令 → 译码执行 → 处理数据 → 写回结果 → 异常时自我管理",
