    "question": "假定某计算机1和计算机2以不同的方式实现了相同的指令集，该指令集中共有A、B、C、D 4类指令，它们所占的比例分别为40%、20%、15%和25%。计算机1和计算机2的时钟周期分别为600MHz和800MHz，各类指令在两计算机上的CPI如下表所示。求两计算机的MIPS各为多少？              各类指令在两计算机上的CPI     指令类型",
    "answer": "答：CPI1＝ 2*40% + 3*20% + 4*15% + 5*25% = 3.25 MIPS1＝ f/CPI1 = 600/3.25 = 185 CPI2＝2*40% + 2* 20% + 3*15% + 4*25% = 2.65 MIPS2＝ f/CPI2 = 800/2.65 = 302",
